import React from 'react';
import {
  Box,
  Button,
  Card,
  CardActionArea,
  CardContent,
  Grid,
  Stack,
  Typography,
} from '@mui/material';
import {
  AccountBalance as BankIcon,
  Public as ExportIcon,
  Storefront as BuyerIcon,
  Summarize as GeneralIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';
import {
  REPORTING_INTENT_OPTIONS,
  type ReportingIntentId,
} from '../../constants/reportingUxLabels';

const INTENT_ICONS: Record<ReportingIntentId, React.ReactElement> = {
  buyer_india: <BuyerIcon color="primary" />,
  bank: <BankIcon color="primary" />,
  export_eu: <ExportIcon color="primary" />,
  general: <GeneralIcon color="primary" />,
};

type ReportingIntentWizardProps = {
  onSelectIntent: (tabIndex: number) => void;
  compact?: boolean;
};

const ReportingIntentWizard: React.FC<ReportingIntentWizardProps> = ({
  onSelectIntent,
  compact = false,
}) => (
  <Box sx={{ mb: compact ? 2 : 3 }}>
    <Typography variant={compact ? 'subtitle1' : 'h6'} fontWeight={700} gutterBottom>
      What do you need a report for?
    </Typography>
    <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 720 }}>
      Pick the closest match — we open the right report and show available downloads with readiness status.
    </Typography>
    <Grid container spacing={2}>
      {REPORTING_INTENT_OPTIONS.map((intent) => (
        <Grid item xs={12} sm={6} key={intent.id}>
          <Card variant="outlined" sx={{ height: '100%' }}>
            <CardActionArea onClick={() => onSelectIntent(intent.tabIndex)} sx={{ height: '100%' }}>
              <CardContent>
                <Stack direction="row" spacing={1.5} alignItems="flex-start">
                  {INTENT_ICONS[intent.id]}
                  <Box>
                    <Typography variant="subtitle2" fontWeight={700}>
                      {intent.title}
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                      {intent.subtitle}
                    </Typography>
                    <Typography variant="caption" color="primary.main" display="block" sx={{ mt: 1 }}>
                      {intent.deliverable}
                    </Typography>
                  </Box>
                </Stack>
              </CardContent>
            </CardActionArea>
          </Card>
        </Grid>
      ))}
    </Grid>
    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ mt: 2 }}>
      <Button component={RouterLink} to="/compliance" variant="outlined" size="small">
        Open Compliance Hub
      </Button>
      <Button component={RouterLink} to={DOCUMENT_UPLOAD_PATH} variant="text" size="small">
        Upload bills first
      </Button>
    </Stack>
  </Box>
);

export default ReportingIntentWizard;
